from decimal import Decimal, ROUND_HALF_UP

_CENT = Decimal("0.01")
_HUNDRED = Decimal(100)
_ZERO_2 = Decimal("0.00")
_ALLOWED_RATES = (Decimal(0), Decimal(4), Decimal(10), Decimal(21))

def _canonical_rate(d: Decimal) -> str:
    if d == Decimal(21):
        return "21"
    if d == Decimal(10):
        return "10"
    if d == Decimal(4):
        return "4"
    return "0"

def vat_breakdown(lines: list[dict], mode: str) -> dict:
    if mode != "PER_LINE" and mode != "PER_INVOICE":
        raise ValueError("invalid mode")
    if not isinstance(lines, list):
        raise ValueError("lines must be a list")
    if len(lines) == 0:
        return {"net": Decimal("0.00"), "vat": Decimal("0.00"), "gross": Decimal("0.00"), "by_rate": {}}
    # validate and collect
    parsed = []
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError("line must be a dict")
        if "quantity" not in line or "unit_net" not in line or "vat_rate" not in line:
            raise ValueError("missing key")
        q = line["quantity"]
        u = line["unit_net"]
        r = line["vat_rate"]
        if type(q) is not int:
            raise ValueError("invalid quantity")
        if q <= 0:
            raise ValueError("invalid quantity")
        if not isinstance(u, str):
            raise ValueError("invalid unit_net")
        try:
            du = Decimal(u)
        except Exception:
            raise ValueError("invalid unit_net")
        if not du.is_finite():
            raise ValueError("invalid unit_net")
        if du < 0:
            raise ValueError("invalid unit_net")
        if du.as_tuple().exponent < -4:
            raise ValueError("invalid unit_net")
        if not isinstance(r, str):
            raise ValueError("invalid vat_rate")
        try:
            dr = Decimal(r)
        except Exception:
            raise ValueError("invalid vat_rate")
        if not dr.is_finite():
            raise ValueError("invalid vat_rate")
        if dr not in _ALLOWED_RATES:
            raise ValueError("invalid vat_rate")
        canon = _canonical_rate(dr)
        parsed.append((q, du, dr, canon))
    by_rate = {}
    if mode == "PER_LINE":
        acc = {}
        for q, du, dr, canon in parsed:
            exact = du * q
            line_net = exact.quantize(_CENT, rounding=ROUND_HALF_UP)
            line_vat = (line_net * dr / _HUNDRED).quantize(_CENT, rounding=ROUND_HALF_UP)
            if canon not in acc:
                acc[canon] = [Decimal("0.00"), Decimal("0.00"), dr]
            acc[canon][0] += line_net
            acc[canon][1] += line_vat
        for canon, (n, v, _dr) in acc.items():
            g = n + v
            by_rate[canon] = {"net": n, "vat": v, "gross": g}
    else:
        exact_sums = {}
        rate_for = {}
        for q, du, dr, canon in parsed:
            exact = du * q
            if canon not in exact_sums:
                exact_sums[canon] = exact
                rate_for[canon] = dr
            else:
                exact_sums[canon] += exact
        for canon, exact_sum in exact_sums.items():
            dr = rate_for[canon]
            gnet = exact_sum.quantize(_CENT, rounding=ROUND_HALF_UP)
            gvat = (gnet * dr / _HUNDRED).quantize(_CENT, rounding=ROUND_HALF_UP)
            ggross = gnet + gvat
            by_rate[canon] = {"net": gnet, "vat": gvat, "gross": ggross}
    total_net = Decimal("0.00")
    total_vat = Decimal("0.00")
    for vals in by_rate.values():
        total_net += vals["net"]
        total_vat += vals["vat"]
    total_gross = total_net + total_vat
    return {"net": total_net, "vat": total_vat, "gross": total_gross, "by_rate": by_rate}
